	public Vector2 size;

	public float delta;

	public List<Point> unlockTrail;

	public void Update(float frameTime)
	{
		delta += frameTime;
		if (delta > (float)Math.PI * 20f)
		{
			delta -= (float)Math.PI * 20f;
		}
	}

	public SkillTreeDraw(Vector2 size)
	{
		this.size = size;
		zoom = 0.3f;
		scroll = default;
	}

	public void MakeTrail(int nodeIdx, PlayerStats pStats)
	{
		unlockTrail = new List<Point>();
		MakeTrailRec(nodeIdx, pStats, unlockTrail);
	}

	private List<Point> MakeTrailRec(int nodeIdx, PlayerStats pStats, List<Point> path)
	{
		for (int i = 0; i < 2; i++)
		{
			if (SkillTree.nodes[nodeIdx].parent[i] > -1)
			{
				Point item = new Point(nodeIdx, i);
				if (!path.Contains(item))
				{
					path.Add(item);
				}
				MakeTrailRec(SkillTree.nodes[nodeIdx].parent[i], pStats, path);
			}
		}
		return null;
	}

	public Vector2 GetScreenLoc(Vector2 realLoc)
	{
		return (realLoc - scroll) * zoom + size / 2f;
	}

